  "summary": "The code contains critical security vulnerabilities (Zip Slip), performance bottlenecks due to blocking I/O, and maintainability issues. The fixed code implements streaming file reads, path sanitization for archives, and environment-based configuration.",
  "fixed_code": "import os\nimport tarfile\nimport uuid\nimport aiofiles\nfrom fastapi import FastAPI, File, HTTPException, UploadFile\n\napp = FastAPI()\nUPLOAD_DIR = os.getenv(\"UPLOAD_DIR\", \"/tmp/uploads\")\nMAX_BYTES = 5 * 1024 * 1024\n\n@app.post(\"/avatars\")\nasync def upload_avatar(file: UploadFile = File(...)):\n    \"\"\"Uploads a PNG avatar with size validation and streaming write.\"\"\"\n    data = await file.read(MAX_BYTES + 1)\n    if len(data) > MAX_BYTES:\n        raise HTTPException(status_code=413, detail=\"file too large\")\n    if not data.startswith(b\"\\x89PNG\\r\\n\\x1a\\n\"):\n        raise HTTPException(status_code=415, detail=\"PNG only\")\n    \n    stored = f\"{uuid.uuid4().hex}.png\"\n    path = os.path.join(UPLOAD_DIR, stored)\n    async with aiofiles.open(path, \"wb\") as fh:\n        await fh.write(data)\n    return {\"stored_as\": stored}\n\ndef import_backup(archive_path: str, dest: str) -> list[str]:\n    \"\"\"Extracts a tar archive safely to the destination directory.\"\"\"\n    os.makedirs(dest, exist_ok=True)\n    with tarfile.open(archive_path) as tar:\n        for member in tar.getmembers():\n            if \"..\" in member.name or member.name.startswith(\"/\"):\n                raise Exception(\"Malicious archive path detected\")\n        tar.extractall(dest, filter=\"data\")\n    return sorted(os.listdir(dest))"
